import importlib.util
spec=importlib.util.spec_from_file_location('task_transform',p)
mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
def mk(h,w,bg, marks):
    g=[[bg]*w for _ in range(h)]
    for r,c,v in marks: g[r][c]=v
    return g
def nz(g,bg): return {(r,c,v) for r,row in enumerate(g) for c,v in enumerate(row) if v!=bg}
# Demo 1
D1=mk(9,9,4,[(2,1,1),(7,6,1)])
E1={(r,c,1) for r,c in [(2,1),(3,2),(4,3),(5,4),(6,5),(7,6)]}
# Demo 2
D2=mk(8,11,8,[(1,6,1),(6,1,1),(3,4,6)])
E2={(r,c,1) for r,c in [(1,6),(2,5),(4,3),(5,2),(6,1)]}|{(r,c,6) for r in range(8) for c in range(11) if r-c==-1}
# Demo 3
D3=mk(9,12,4,[(1,7,1),(7,1,1),(6,7,6)])
E3={(r,c,1) for r,c in [(r,8-r) for r in range(1,8)]}|{(6,7,6)}
# Demo 4
D4=mk(15,12,5,[(3,1,1),(9,7,1),(2,9,6),(5,3,6),(8,6,6),(13,4,6)])
ones4={(r,c,1) for r,c in [(3,1),(4,2),(6,4),(7,5),(9,7)]}
six4={(2,9,6),(13,4,6)}|{(r,c,6) for r in range(15) for c in range(12) if r+c==8 or r+c==14}
E4=ones4|six4
for i,(g,e,bg) in enumerate([(D1,E1,4),(D2,E2,8),(D3,E3,4),(D4,E4,5)],1):
    got=nz(mod.transform(g),bg)
    print(i, got==e, 'missing',sorted(e-got),'extra',sorted(got-e))
